            B.q("ai-m2-7", "ai-container-apps", "Which two settings do you choose? Select two.", listOf("An HTTP scale rule with concurrent requests set to 50", "Minimum replicas of 0, to save money overnight", "Single revision mode", "Minimum replicas of 1"), setOf(0, 3), "An HTTP scale rule adds a replica each time the concurrent requests per replica pass the number you set (the default is 10). Keeping a minimum of one replica means there is always one ready, so no request waits for a cold start, the delay while a replica starts from nothing.",
                scenario = "Kestrel Maps' route API on Azure Container Apps is called by its Android app. One replica (one running copy) comfortably handles about 50 requests at a time, and the first request each morning must not wait for a replica to start.",
