            B.q("ai-m2-13", "ai-container-troubleshoot", "kubectl describe pod shows the event FailedScheduling: 0/3 nodes are available: 3 Insufficient cpu. What do you do?", listOf("Attach the registry with az aks update --attach-acr so the pods can pull", "Lower the CPU requests, or add nodes by scaling the pool or with the cluster autoscaler", "Add a Horizontal Pod Autoscaler that scales the Deployment on CPU use", "Raise the containers' CPU limits so each pod may use more of a node's CPU"), setOf(1), "Pending with Insufficient cpu means no node has enough unreserved CPU left for the pod's request. Either ask for less CPU, or give the cluster more room by adding nodes, by hand or with the cluster autoscaler, which adds nodes when pods cannot be placed.",
                scenario = "After raising the replicas of Kestrel Maps' API Deployment to 12, four of the new pods stay Pending.",
