    // Data
            B.q("ai-m2-15", "ai-cosmos-sdk", "The phone shows 20 workouts per screen and asks for the next page later, in a new HTTP request. What should the API return with each page so the next request can carry on where the last one stopped?", listOf("The id of the last item on the page, used later in WHERE c.id > @last", "The session token from the page's response, sent back with the next query", "The continuation token from by_page(), passed back to by_page() next time", "The page number, turned into OFFSET @n LIMIT 20 on the next query"), setOf(2), "A continuation token is an opaque bookmark that Cosmos DB hands back with each page of query results. Passing it to by_page() on the same query resumes exactly after the last page, at a steady cost per page.",
                scenario = "Orbit Fitness has an Android app that lists a user's workout history from a Cosmos DB for NoSQL container partitioned by /userId. The Python API runs on Azure Container Apps.",
                whyWrong = mapOf(
                    0 to "Ids are not ordered by time, and building your own paging this way skips or repeats items when new workouts arrive.",
