            B.q("ai-m2-17", "ai-cosmos-perf", "Which throughput option keeps the bill lowest for this workload?", listOf("Manual provisioned throughput of 400 RU/s on the container", "Autoscale throughput with a maximum of 4,000 RU/s, scaling down when idle", "Shared database throughput of 400 RU/s across all the app's containers", "A serverless account, billed per request unit consumed"), setOf(3), "Serverless charges per request unit consumed and has no hourly floor, which suits light, irregular traffic such as a prototype or a dev environment. Provisioned and autoscale throughput bill every hour whether or not requests arrive.",
                scenario = "Tideline Recipes is testing a prototype Android app with 30 internal testers. The Cosmos DB container sees a few hundred requests a day, in short bursts, and sits idle for hours.",
                whyWrong = mapOf(
