            B.q("ai-m2-19", "ai-cosmos-perf", "Chat threads must be deleted automatically 30 days after their last change, except threads the user pinned, which stay forever. No clean-up code may run. What do you configure? Select two.", listOf("Set the container's default time to live (defaultTtl) to 2592000 seconds", "Set ttl to -1 on pinned thread items", "A timer-triggered function that queries for old threads and deletes them", "Strong consistency, so deletes are not missed"), setOf(0, 1), "TTL (time to live) makes Cosmos DB delete expired items in the background, using spare throughput. The container default applies to every item, and an item's own ttl overrides it; -1 means the item never expires.",
                scenario = "Fernway Health stores in-app chat threads with a care coach in Cosmos DB for NoSQL. Privacy rules say unpinned threads must vanish after 30 days.",
