            B.q("ai-m2-26", "ai-postgres", "A one-off Python job must load two million ride rows into PostgreSQL as fast as possible. Which approach?", listOf("One INSERT per row, each committed in its own transaction", "Stream the rows with cursor.copy(\"COPY rides FROM STDIN\")", "cursor.executemany() with a parameterized INSERT, committed once", "One multi-row INSERT built by formatting all the rows into a string"), setOf(1), "COPY is PostgreSQL's bulk-load command: rows stream over one connection with very little per-row overhead, which is far faster than individual INSERTs.",
                scenario = "Pedalo is migrating historical rides from an old system into Azure Database for PostgreSQL flexible server.",
                whyWrong = mapOf(
