            B.q("ai-m2-53", "ai-appconfig", "Before each release the team wants a frozen copy of the settings it tested, and production must load exactly that copy. Which two statements about App Configuration snapshots are true? Select two.", listOf("A snapshot can be edited in place to fix one value", "Loading a snapshot also needs a label_filter on the same selector", "A snapshot is immutable: later edits to the keys do not change it", "The app loads it with SettingSelector(snapshot_name=\"release-7\")"), setOf(2, 3), "A snapshot is a named, unchangeable set of key-values captured at one moment. The Python provider loads it by name with a snapshot selector, so production gets exactly the set that was tested, whatever has changed in the store since.",
                scenario = "TrailMate's hiking Android app gets route limits and model settings from a Python backend on Azure Container Apps.",
                whyWrong = mapOf(
                    0 to "Snapshots cannot be changed. To fix a value you create a new snapshot.",
                    1 to "snapshot_name cannot be combined with key, label or tag filters on the same selector.",
                ),
            ),
            B.q("ai-m2-54", "ai-appconfig", "The release pipeline must load the settings in appsettings.prod.json into the store under the prod label. Which command does it run?", listOf("az appconfig create --name bd-config --label prod", "az appconfig kv set --name bd-config --key appsettings.prod.json", "az keyvault secret set --vault-name bd-kv --name settings --file appsettings.prod.json", "az appconfig kv import --name bd-config --source file --path appsettings.prod.json --format json --label prod"), setOf(3), "az appconfig kv import reads a file (JSON, YAML or properties) and writes each entry as a key-value, with the label you give. The pipeline's identity needs a role that can write, such as App Configuration Data Owner.",
                scenario = "Brightdesk, a help-desk Android app, keeps its backend settings in JSON files in the repository and is moving them into Azure App Configuration.",
                whyWrong = mapOf(
                    0 to "az appconfig create makes a new store. It neither takes a label nor imports anything.",
                    1 to "kv set writes a single key, here one named after the file, not the settings inside it.",
