            B.q("ai-m2-60", "ai-kql", "The same two-hour window and role name appear in three parts of a long query. How do you define them once and reuse them?", listOf("extend window = 2h, role = \"bd-api\" in the first part of the query", "project window = 2h, role = \"bd-api\" at the top of the query", "let window = 2h; let role = \"bd-api\"; at the start of the query", "set window = 2h; set role = \"bd-api\"; before the query"), setOf(2), "let binds a name to a value, a table or a function at the start of a query, and every later statement can use it, so a change in one place changes every use.",
                scenario = "Brightdesk's on-call engineer keeps a saved query that compares requests, dependencies and exceptions for the bd-api role.",
